53	const PROCESSING_FEE = 5;
54	const FIRST_INSURANCE_RATE = 0.1;
55	const CURSE_SURCHARGE_RATE = 0.5;
56	const HIGH_ENCHANTMENT_THRESHOLD = 5;
57	const ENCHANTMENT_SURCHARGE_RATE = 0.3;
58	const LOYALTY_MIN_YEARS = 2;
59	const LOYALTY_DISCOUNT_RATE = 0.2;
60	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
61	
62	const BASE_PREMIUMS: Record<string, number> = {
63	  sword: 100,
64	  amulet: 60,
65	  staff: 80,
66	  potion: 40,
67	  rune: 25,
68	  moonstone: 25,
69	};
70	
71	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
72	const COMPONENT_BLOCK_SIZE = 3;
73	const COMPONENT_BLOCK_PREMIUM = 60;
74	
75	const roundUpInMHPCOsFavor = Math.ceil;
76	const roundDownInMHPCOsFavor = Math.floor;
77	
78	const basePremiumFor = (type: string, count: number): number => {
79	  if (!(type in BASE_PREMIUMS)) {
80	    throw new Error(`unknown item type: "${type}"`);
81	  }
82	  const isComponentBlock =
83	    COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE;
84	  return isComponentBlock
85	    ? COMPONENT_BLOCK_PREMIUM
86	    : count * BASE_PREMIUMS[type];
87	};
88	
89	const countBy = <T>(
90	  items: T[],
91	  typeOf: (item: T) => string,
92	): Map<string, number> => {
93	  const countsByType = new Map<string, number>();
94	  for (const item of items) {
95	    const type = typeOf(item);
96	    countsByType.set(type, (countsByType.get(type) ?? 0) + 1);
97	  }
98	  return countsByType;
99	};
100	
101	const countItemsByType = (items: QuoteItem[]): Map<string, number> =>
102	  countBy(items, (item) => item.type);
103	
104	const isCursed = (item: QuoteItem): boolean => item.cursed === true;
105	
106	const isHighlyEnchanted = (item: QuoteItem): boolean =>
107	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
108	
109	const perItemSurcharge = (
110	  items: QuoteItem[],
111	  applies: (item: QuoteItem) => boolean,
112	  rate: number,
113	): number =>
114	  items.reduce(
115	    (total, item) =>
116	      total + (applies(item) ? BASE_PREMIUMS[item.type] * rate : 0),
117	    0,
118	  );
119	
120	const quotePremium = (
121	  items: QuoteItem[],
122	  customer: Customer,
123	  isFollowUpContract: boolean,
124	): number => {
125	  const basePremium = [...countItemsByType(items)].reduce(
126	    (total, [type, count]) => total + basePremiumFor(type, count),
127	    0,
128	  );
129	  const curseSurcharge = perItemSurcharge(items, isCursed, CURSE_SURCHARGE_RATE);
130	  const enchantmentSurcharge = perItemSurcharge(
131	    items,
132	    isHighlyEnchanted,
133	    ENCHANTMENT_SURCHARGE_RATE,
134	  );
135	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_RATE;
136	  const loyaltyDiscount =
137	    customer.yearsWithMHPCO >= LOYALTY_MIN_YEARS
138	      ? basePremium * LOYALTY_DISCOUNT_RATE
139	      : 0;
140	  const followUpDiscount = isFollowUpContract
141	    ? basePremium * FOLLOW_UP_DISCOUNT_RATE
142	    : 0;
143	  return roundUpInMHPCOsFavor(
144	    basePremium +
145	      curseSurcharge +
146	      enchantmentSurcharge +
147	      firstInsuranceSurcharge -
148	      loyaltyDiscount -
149	      followUpDiscount +
150	      PROCESSING_FEE,
151	  );
152	};
153	
154	const INSURANCE_VALUES: Record<string, number> = {
155	  sword: 1000,
156	  amulet: 600,
157	  rune: 250,
158	};
159	
160	const DEDUCTIBLE = 100;
161	const PAYOUT_CAP_MULTIPLIER = 2;
162	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
163	const HALF_REIMBURSEMENT_RATE = 0.5;
164	
165	const reimbursementFor = (damage: Damage, policyItems: QuoteItem[]): number => {
166	  const damagedItem = policyItems.find(
167	    (item) => item.type === damage.itemType,
168	  );
169	  const isHalfReimbursed =
170	    (damagedItem?.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
171	  return isHalfReimbursed
172	    ? damage.amount * HALF_REIMBURSEMENT_RATE
173	    : damage.amount;
174	};
175	
176	const assertDamagesWithinInsuredCounts = (
177	  damages: Damage[],
178	  policyItems: QuoteItem[],
179	): void => {
180	  const insuredCounts = countItemsByType(policyItems);
181	  for (const [type, damageCount] of countBy(
182	    damages,
183	    (damage) => damage.itemType,
184	  )) {
185	    const insuredCount = insuredCounts.get(type) ?? 0;
186	    if (damageCount > insuredCount) {
187	      throw new Error(
188	        `claim rejected: ${damageCount} damage entries for "${type}" but only ${insuredCount} insured`,
189	      );
190	    }
191	  }
192	};
193	
194	const settleClaim = (
195	  claimStep: ClaimStep,
196	  policyItems: QuoteItem[],
197	  remainingCapBefore: number,
198	): ClaimResult => {
199	  assertDamagesWithinInsuredCounts(claimStep.incident.damages, policyItems);
200	  const uncappedPayout = roundDownInMHPCOsFavor(
201	    claimStep.incident.damages.reduce(
202	      (total, damage) =>
203	        total + (reimbursementFor(damage, policyItems) - DEDUCTIBLE),
204	      0,
205	    ),
206	  );
207	  const payout = Math.min(uncappedPayout, remainingCapBefore);
208	  return { payout, remainingCap: remainingCapBefore - payout };
209	};
210	
211	const initialPayoutCap = (policyItems: QuoteItem[]): number => {
212	  const insuranceSum = policyItems.reduce(
213	    (sum, item) => sum + INSURANCE_VALUES[item.type],
214	    0,
215	  );
216	  return insuranceSum * PAYOUT_CAP_MULTIPLIER;
217	};
218	
219	export const runScenario = (scenario: Scenario): ScenarioOutput => {
220	  const remainingCapByPolicy = new Map<number, number>();
221	  const results = scenario.steps.map((step, stepIndex): StepResult => {
222	    if (step.op === "claim") {
223	      const policyStep = scenario.steps[step.policy] as QuoteStep;
224	      const remainingCapBefore =
225	        remainingCapByPolicy.get(step.policy) ??
226	        initialPayoutCap(policyStep.items);
227	      const result = settleClaim(step, policyStep.items, remainingCapBefore);
228	      remainingCapByPolicy.set(step.policy, result.remainingCap);
229	      return result;
230	    }
231	    const isFollowUpContract = stepIndex > 0;
232	    return {
233	      premium: quotePremium(step.items, scenario.customer, isFollowUpContract),
234	    };
235	  });
236	  return { results };
237	};
